import{_ as a,o as e,c as o,ai as s}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"安全审核与授权","description":"审批卡片怎么看、自动审核规则怎么设、密码和验证码怎么交接，一页讲清。","frontmatter":{"related":["/basics/drafts-first","/basics/local-computer","/faq/faq"],"title":"安全审核与授权","description":"审批卡片怎么看、自动审核规则怎么设、密码和验证码怎么交接，一页讲清。","section":"basics","order":7,"tags":["基础","安全","审批","隐私"],"sources":["https://docs.x.ai/grok-bot/approvals-security-and-privacy","https://docs.x.ai/grok-bot/faq","https://cursor.com/help/grok-bot/faqs"],"wordCount":797,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"安全审核与授权 | WANGXXXL"}],["meta",{"property":"og:description","content":"审批卡片怎么看、自动审核规则怎么设、密码和验证码怎么交接，一页讲清。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/safety-approvals"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-safety-approvals-649a812a06.png"}],["meta",{"property":"og:image:alt","content":"安全审核与授权 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"安全审核与授权 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"审批卡片怎么看、自动审核规则怎么设、密码和验证码怎么交接，一页讲清。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-safety-approvals-649a812a06.png"}],["meta",{"name":"twitter:image:alt","content":"安全审核与授权 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/safety-approvals"}]]},"headers":[],"relativePath":"basics/safety-approvals.md","filePath":"basics/safety-approvals.md","lastUpdated":1792485206000}'),i={name:"basics/safety-approvals.md"};function l(n,t,r,p,c,d){return e(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="安全审核与授权" tabindex="-1">安全审核与授权 <a class="header-anchor" href="#安全审核与授权" aria-label="Permalink to &quot;安全审核与授权&quot;">​</a></h1><p>让 AI 替你在真实世界里动手，最需要想清楚的就是：<strong>哪些事它能自己做，哪些事必须你点头</strong>。Grok Bot 为此设计了几道关。</p><h2 id="第一道关-在任务里写明边界" tabindex="-1">第一道关：在任务里写明边界 <a class="header-anchor" href="#第一道关-在任务里写明边界" aria-label="Permalink to &quot;第一道关：在任务里写明边界&quot;">​</a></h2><p>最简单也最有效。交代任务时直接说清楚哪里要停：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个月的投放数据核对一遍，给出调整预算的建议。</span></span>
<span class="line"><span>不要修改任何投放设置，不要联系代理商。</span></span>
<span class="line"><span>建议里写清楚：当前值、建议值、预期影响，等我确认。</span></span></code></pre></div><p>以下几类动作，建议一律写上&quot;先问我&quot;：发送消息或邀请、发布内容、付款和转账、删除或覆盖数据、修改权限、改动线上系统、接受法律条款。</p><h2 id="第二道关-审批卡片" tabindex="-1">第二道关：审批卡片 <a class="header-anchor" href="#第二道关-审批卡片" aria-label="Permalink to &quot;第二道关：审批卡片&quot;">​</a></h2><p>当 Bot 准备执行有风险的动作时，对话里会出现审批卡片，列出要做什么、对谁做、用什么参数。常见选项：</p><ul><li><strong>允许一次</strong>：只放行这一次。</li><li><strong>始终允许</strong>：保存为规则，以后同类动作自动放行。</li><li><strong>拒绝</strong>：不执行。</li></ul><div class="warning custom-block"><p class="custom-block-title">看不懂就别批</p><p>如果你说不清楚这个动作的目标和后果，就不要批准。让它用大白话解释，或者先出草稿。另外，审批只决定&quot;接下来做不做&quot;，不会撤销已经完成的工作。</p></div><p><strong>关于过期</strong>：你正在对话时出现的审批会一直等你。但例程、事件触发或其他 Bot 发起的工作中出现的审批，大约 10 分钟没人处理就会过期，动作不会执行。想不错过，可以打开该 Bot 的通知。</p><h2 id="第三道关-自动审核规则" tabindex="-1">第三道关：自动审核规则 <a class="header-anchor" href="#第三道关-自动审核规则" aria-label="Permalink to &quot;第三道关：自动审核规则&quot;">​</a></h2><p>开启自动审核后，系统会在每次工具调用和电脑操作前做一次检查。你可以在设置里添加两类规则：</p><ul><li><strong>先问我</strong>：匹配的动作一律停下等你。</li><li><strong>自动允许</strong>：匹配的动作在检查没发现其他问题时直接放行。</li></ul><p>两类都匹配时，&quot;先问我&quot;优先。规则要写得窄而具体，例如：</p><ul><li>发送任何外部邮件前先问我。</li><li>修改线上看板前先问我。</li><li>在某个报表目录里执行只读命令时自动允许。</li></ul><p>避免&quot;浏览器里的操作全部允许&quot;这种宽泛规则。</p><h2 id="密码和验证码-你来输" tabindex="-1">密码和验证码：你来输 <a class="header-anchor" href="#密码和验证码-你来输" aria-label="Permalink to &quot;密码和验证码：你来输&quot;">​</a></h2><p>密码、通行密钥、两步验证码、人机验证、支付确认，Bot 会把电脑交给你接管。网页需要你填登录信息、地址、手机号时，它也可能在聊天里弹出安全表单，你填写后由它填进网页；表单内容会被遮挡，不进入对话记录。<strong>任何时候都不要把密码直接打在聊天里。</strong></p><h2 id="用最小权限" tabindex="-1">用最小权限 <a class="header-anchor" href="#用最小权限" aria-label="Permalink to &quot;用最小权限&quot;">​</a></h2><ul><li>只连接必要的应用，能只读就只读。</li><li>先从只读任务和草稿开始，信任建立后再逐步放开。</li><li>定期检查已连接的应用和正在运行的例程。</li><li>项目结束后：暂停例程、退出网站登录、移除连接器、删除敏感文件。</li></ul><div class="tip custom-block"><p class="custom-block-title">关于隐私</p><p>数据如何存储、是否用于训练等，遵循你账号的隐私设置和官方隐私政策，以官方最新说明为准。不要把不想让所有 Bot 接触的凭证或文件放在云电脑上。</p></div>`,22)])])}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
